void Page_Load(object sender, EventArgs e)
        {
            ImageNDocServiceUrl = System.Configuration.ConfigurationManager.AppSettings["ImageNDocService"] ?? "";

            lblMessage.Text = "";
            lblMessage.ForeColor = System.Drawing.Color.Empty;
            lblMessage.CssClass = "blank";

            AppBaseFunctions.DateCulture();
            if (!Page.IsPostBack)
            {
                DBHelper dbHelper = new DBHelper();
                string sqlGetTypes = "SELECT row_id, new_expense_type FROM ExpenseType ORDER BY row_id ASC";
                DataSet dsTypes = dbHelper.ExecuteDataSet(sqlGetTypes, null, CommandType.Text);
                AppBaseFunctions.populateDropDown(ddlexpensetype, dsTypes, "new_expense_type", "row_id", true, "Select Expense Type");

                string practiceId = HttpContext.Current.Session["practice_id"].ToString();
                string sqlGetUsers = "SELECT row_id, firstname + ' ' + lastname AS username FROM Appuser WHERE ('" + practiceId + "' = '0' OR '" + practiceId + "' = '' OR practice_id IN (SELECT TRY_CAST(value AS numeric) FROM dbo.SplitString('" + practiceId + "', ','))) ORDER BY firstname ASC";
                DataSet dsUsers = dbHelper.ExecuteDataSet(sqlGetUsers, null, CommandType.Text);
                AppBaseFunctions.populateDropDown(ddlAppUser, dsUsers, "username", "row_id", true, "Select App User");

                txtdate.Text = System.DateTime.Now.ToString("dd/MM/yyyy");        
            }
        }

