function validateFileCount(input) {
            var existingStr = $('#hfExistingBillImagePath').val();
            var existingCount = existingStr ? existingStr.split(/[,|]/).filter(function(e){ return e; }).length : 0;
            var currentPending = pendingDt.files.length;
            var maxAllowed = 5 - existingCount - currentPending;

            if (input.files.length > maxAllowed && maxAllowed >= 0) {
                alert("You can only have a maximum of 5 files total (including existing files).");
            }

            var addedCount = 0;
            for (var i = 0; i < input.files.length; i++) {
                if (addedCount < maxAllowed) {
                    pendingDt.items.add(input.files[i]);
                    addedCount++;
                }
            }

            input.files = pendingDt.files;
            renderEditImageLinks();
        }

function saveExpense() {
            // Validate client-side first
            if (typeof Page_ClientValidate === 'function' && !Page_ClientValidate("AddExpenses")) {
                return false;
            }

            var amount = parseFloat($('#<%= txtexpenseamount.ClientID %>').val());
            if (isNaN(amount) || amount <= 0) {
                $('#<%= lblMessage.ClientID %>').text('Expense Amount must be greater than zero.').css('color', 'red');
                return false;
            }

            if (amount > 50000) {
                $('#<%= lblMessage.ClientID %>').text('Expense Amount cannot exceed 50,000 at one time.').css('color', 'red');
                return false;
            }

            var description = $('#<%= txtexpensedescription.ClientID %>').val().trim();
            if (description === "") {
                $('#<%= lblMessage.ClientID %>').text('Expense Description is mandatory.').css('color', 'red');
                return false;
            }

            var rowId = parseInt($('#hfRowId').val() || '0');
            var oldAmount = parseFloat($('#hfOldAmount').val() || '0');
            var netAmount = rowId > 0 ? (amount - oldAmount) : amount;

            var remBalStr = $('#<%= lblRemainingBalance.ClientID %>').text().replace(/[^0-9.-]+/g, "");
            var remainingBalance = parseFloat(remBalStr);

            if (!isNaN(remainingBalance) && netAmount > remainingBalance) {
                var msg = rowId > 0 
                    ? "Warning: The net increase (₹" + netAmount + ") exceeds your Remaining Balance (₹" + remainingBalance + ").\n\nDo you want to continue saving this expense?"
                    : "Warning: The entered amount (₹" + amount + ") exceeds your Remaining Balance (₹" + remainingBalance + ").\n\nDo you want to continue saving this expense?";
                var proceed = confirm(msg);
                if (!proceed) {
                    return false;
                }
            }

