                ExpenseType: parseInt($('#<%= ddlexpensetype.ClientID %>').val() || '0'),
                Description: $('#<%= txtexpensedescription.ClientID %>').val(),
                PracticeId: 0,
                ExistingBillImagePath: $('#hfExistingBillImagePath').val() || '',
                OldAmount: $('#hfOldAmount').val() ? parseFloat($('#hfOldAmount').val()) : null,
                OldExpenseType: $('#hfOldExpenseType').val() ? parseInt($('#hfOldExpenseType').val()) : null,
                OldDescription: $('#hfOldDescription').val() || null
            };

