            var fileUpload = document.getElementById('<%= fubillimage.ClientID %>');
            if (fileUpload && fileUpload.files.length > 0) {
                for (var i = 0; i < fileUpload.files.length; i++) {
                    formData.append('file_' + i, fileUpload.files[i]);
                }
            }

            var btnId = model.RowId > 0 ? '#btnUpdate' : '#btnSubmit';
            var origText = $(btnId).val();
            $(btnId).val('Saving...').prop('disabled', true);

